let rota = '';
if ($('App envia (in)').isExecuted) rota = 'in';
else if ($('App busca (out)').isExecuted) rota = 'out';
else if ($('Painel (api)').isExecuted) rota = 'painel';
const req = $input.first().json || {};
let body = {};
let token = '';
if (rota === 'in' || rota === 'out') {
  body = req.body || {};
} else if (rota === 'painel') {
  const raw = req.body && typeof req.body.d === 'string' ? req.body.d : '{}';
  try { body = JSON.parse(raw); } catch (e) { body = {}; }
  token = String(body.token || '');
  delete body.token;
}
const json = JSON.stringify({ rota, token, body });
const b64 = typeof Buffer !== 'undefined'
  ? Buffer.from(json, 'utf8').toString('base64')
  : btoa(unescape(encodeURIComponent(json)));
return [{ json: { rota, sql: `select suporte.api(convert_from(decode('${b64}', 'base64'), 'UTF8')::jsonb) as r` } }];

const alvo = $('Postgres suporte.api').first().json.r || {};
const resp = $input.first().json || {};
const toIso = (s) => {
  const t = String(s || '').trim();
  const m = t.match(/^(\d{2})\/(\d{2})\/(\d{4})[ T]?(\d{2}:\d{2}(?::\d{2})?)?/);
  if (m) return `${m[3]}-${m[2]}-${m[1]}T${m[4] || '00:00'}-03:00`;
  return t;
};
const lista = Array.isArray(resp.TrackingEvents) ? resp.TrackingEvents : [];
const eventos = lista.map(e => ({
  quando: toIso(e.EventDateTime),
  local: e.EventLocation || '',
  descricao: e.EventDescription || '',
  tipo: e.EventType || ''
})).sort((a, b) => (Date.parse(b.quando) || 0) - (Date.parse(a.quando) || 0)).slice(0, 20);
let erro = resp.ErrorMessage || '';
if (!erro && resp.error) erro = resp.error.message || String(resp.error);
if (!erro && !eventos.length) erro = 'sem_eventos';
const dados = { ok: eventos.length > 0, erro, url: resp.TrackingUrl || '', servico: resp.ServiceDescrition || '', eventos };
const json = JSON.stringify({ rota: 'rastreio_salvar', token: '', body: { codigo: alvo.codigo, dados } });
const b64 = typeof Buffer !== 'undefined'
  ? Buffer.from(json, 'utf8').toString('base64')
  : btoa(unescape(encodeURIComponent(json)));
return [{ json: { sql: `select suporte.api(convert_from(decode('${b64}', 'base64'), 'UTF8')::jsonb) as r` } }];

const r0 = $('Postgres suporte.api').first().json.r || {};
const codigos = r0.ocorr_codigos || [];
const objs = $input.all().map(i => i.json || {});
const parse = (v) => { if (typeof v !== 'string') return v; try { return JSON.parse(v); } catch (e) { return v; } };
const ocorrencias = [];
for (const codigo of codigos) {
  const registros = {};
  for (const o of objs) {
    for (const [k, v] of Object.entries(o)) {
      if (k.startsWith('painel:') && k.endsWith(':' + codigo)) registros[k.slice(7, -(codigo.length + 1))] = parse(v);
    }
  }
  if (Object.keys(registros).length) ocorrencias.push({ codigo, registros });
}
return [{ json: { r: { ok: true, ocorrencias } } }];

const ia = ($('Postgres suporte.api').first().json.r || {}).ia || {};
const json = JSON.stringify({ rota: 'ia_contexto', token: '', body: { conv: ia.conv, ultimo_in: ia.ultimo_in } });
const b64 = Buffer.from(json, 'utf8').toString('base64');
return [{ json: { sql: `select suporte.api(convert_from(decode('${b64}', 'base64'), 'UTF8')::jsonb) as r` } }];

const r = $input.first().json.r || {};
const ctx = r.ctx;
if (!ctx) return [];
const msgs = ctx.msgs || [];
let ultOut = -1;
msgs.forEach((m, i) => { if (m.d === 'out') ultOut = i; });
const novas = msgs.slice(ultOut + 1).filter(m => m.d === 'in');
const IGNORA = /^(votou em:|liga[cç][aã]o de (voz|v[ií]deo) perdida|\[[aá]udio\]\s*$)/i;
const texto = novas.map(m => String(m.t || '').trim()).filter(t => t && !IGNORA.test(t)).join('\n').slice(0, 1500);
if (!texto) return [];
const cfg = ctx.cfg || {};
const crm = ctx.crm || {};
const pagos = Number(crm.pedidos) || 0;
const cli = ctx.cliente && !ctx.cliente.erro ? ctx.cliente : null;
const peds = (cli && cli.ultimos_pedidos) || [];
const diasDesde = d => d ? (Date.now() - Date.parse(d)) / 86400000 : 9999;
const transito = peds.find(p => p.status === 'Em transporte' && p.rastreio && diasDesde(p.criado) < 90) || null;
const preparando = peds.find(p => ['Faturado', 'Pagamento aprovado'].includes(p.status) && diasDesde(p.criado) < 60) || null;
const situacao = pagos > 0 ? (transito ? 'cliente_em_transito' : preparando ? 'cliente_preparando' : 'cliente_ja_recebeu')
  : (crm.situacao === 'aguardando_pagamento' ? 'pedido_aguardando_pagamento' : 'sem_compra');
const base = { conv: ctx.conv, ultimo_in: ctx.ultimo_in, situacao, pagos, texto, ctx: { nome: ctx.nome, refs: ctx.refs || [], cfg, modelos: ctx.modelos || {}, msgs, vendas_24h: Number(ctx.vendas_24h) || 0 }, transito, preparando };
const humano = motivo => [{ json: { ...base, classificar: false, acao: 'humano', motivo } }];

const PROBLEMA = /(golpe|golpis|fraud|falso|falsa|clonad|taxa|cobran|cobrad|procon|advogad|justi[cç]a|processar|reclam|reembols|devolu|devolv|estorn|cancel|troca|trocar|defeit|quebrad|vazad|vazou|avaria|amassad|errad|alerg|rea[cç][aã]o|ardeu|ardendo|ard[eê]ncia|queim|coceira|co[cç]ando|irrit|feri(da|u)|manch(ou|ando)|piorou|vermelh|\bard(e|eu|endo|ia)\b|descam|escurec|inchad|bolha|preju[ií]zo|urg[eê]ncia|documento|n[aã]o (chegou|recebi|veio|funcion|fez efeito)|atras|extravi|sumiu|roubad|nota fiscal|denunc|absurd|vergonha|engan|palha[cç]|lixo|horr[ií]vel|p[eé]ssim|raiva|desrespeit|ningu[eé]m (me )?respond|atendente|humano|pessoa de verdade|gerente)/i;
const PEDIDO = /(meu pedido|fiz (um|o|meu) pedido|j[aá] comprei|eu comprei|comprei (o|um|uma|a|dois|2)|minha compra|minha encomenda|meu rastreio|meu c[oó]digo|c[oó]digo de rastr|rastrear|rastreamento|rastreio|n[uú]mero do pedido|j[aá] paguei|paguei|comprovante|pix (que )?(eu )?fiz)/i;

const m = texto.match(PROBLEMA);
if (m) return humano(`palavra de problema: "${m[0]}"`);
if (novas.some(x => /^\[foto\]/.test(String(x.t || '')))) return humano('mandou foto (a IA não vê foto)');
if (pagos === 0) {
  const p = texto.match(PEDIDO);
  if (p) return humano(`fala de pedido sem compra nesse número: "${p[0]}"`);
  if (cfg.ia_venda !== 'sim') return [];
  if (base.ctx.vendas_24h >= 20) return [];
} else if (cfg.ia_rastreio !== 'sim') return [];

const SYSTEM = `Você é o roteador do WhatsApp de SUPORTE da Face Clean (skincare). Leia as últimas mensagens da pessoa e o contexto e responda SOMENTE JSON {"acao":"...","motivo":"até 12 palavras"}.
Ações:
- rastreio: só quer o código/link de rastreio ou saber onde está o pedido, SEM reclamar de atraso nem de problema.
- status: quer saber do pedido que ainda não foi enviado (quando vai ser postado, se já saiu), sem reclamar.
- venda: ainda não comprou e tem dúvida de produto, preço, modo de uso, pagamento antes da compra, frete ou prazo antes de comprar, ou só cumprimentou / veio do anúncio.
- humano: qualquer problema ou pós-venda que não seja só pedir rastreio: atraso, não chegou, extravio, produto errado ou avariado, reação ou alergia, troca, devolução, reembolso, cancelamento, cobrança, taxa, golpe, site ou anúncio falso, já pagou e não achou o pedido, comprou com outro número, nota fiscal, irritação ou raiva, pediu atendente, cantada ou assédio, ou qualquer coisa que você não entendeu.
- nada: só agradecimento, ok, emoji ou figurinha, sem pergunta.
Na dúvida entre humano e qualquer outra ação: humano.`;
const conversa = msgs.slice(-10).map(x => `${x.d === 'in' ? 'pessoa' : 'loja'}: ${String(x.t || '').slice(0, 300)}`).join('\n');
const user = JSON.stringify({ situacao, conversa, mensagens_novas: texto });
return [{ json: { ...base, classificar: true, body: { model: 'gpt-4o-mini', temperature: 0, max_tokens: 80, response_format: { type: 'json_object' }, messages: [{ role: 'system', content: SYSTEM }, { role: 'user', content: user }] } } }];

const b = $('IA: prepara').first().json;
const j = $input.first().json || {};
let acao = b.acao || '', motivo = b.motivo || '';
if (b.classificar) {
  const c = j.choices && j.choices[0] && j.choices[0].message && j.choices[0].message.content;
  if (!c) return [];
  try { const o = JSON.parse(c); acao = String(o.acao || '').toLowerCase(); motivo = 'IA: ' + String(o.motivo || '').slice(0, 120); } catch (e) { return []; }
}
const cfg = b.ctx.cfg || {};
const refs = new Set(b.ctx.refs || []);
const primeiro = n => { const p = String(n || '').trim().split(/\s+/)[0] || ''; return /^\p{L}/u.test(p) ? p[0].toUpperCase() + p.slice(1).toLowerCase() : ''; };
const data = d => { if (!d) return ''; const m = String(d).match(/^(\d{4})-(\d{2})-(\d{2})$/); if (m) return `${m[3]}/${m[2]}/${m[1]}`; const x = new Date(d); return isNaN(x) ? '' : x.toLocaleDateString('pt-BR', { timeZone: 'America/Fortaleza' }); };
const hora = d => { const x = new Date(d); return isNaN(x) ? '' : x.toLocaleString('pt-BR', { timeZone: 'America/Fortaleza', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }); };
function render(t, v) {
  let s = String(t || '');
  if (!v.nome) s = s.replace(/,?\s*\{nome\}/g, '');
  return s.split('\n').filter(l => [...l.matchAll(/\{(\w+)\}/g)].every(m => v[m[1]] !== undefined && String(v[m[1]]).trim() !== ''))
    .map(l => l.replace(/\{(\w+)\}/g, (m, k) => v[k])).join('\n').replace(/\n{3,}/g, '\n\n').trim();
}
function vars(p) {
  const cache = p.rastreio_cache && p.rastreio_cache.dados;
  const ev = cache && Array.isArray(cache.eventos) && cache.eventos[0];
  const fresco = p.rastreio_cache && (Date.now() - Date.parse(p.rastreio_cache.em)) < 48 * 3600000;
  return {
    nome: primeiro(b.ctx.nome), pedido: p.numero || '', rastreio: p.rastreio || '', link_rastreio: p.rastreio_url || '',
    previsao: data(p.previsao), status: p.status || '', transportadora: p.transportadora || '',
    ultima_atualizacao: ev && fresco ? `${ev.descricao || ''}${ev.local ? ' — ' + ev.local : ''}${ev.quando ? ' (' + hora(ev.quando) + ')' : ''}`.trim() : '',
    aviso_envio: /MINI_ENVIOS/i.test(p.transportadora || '') ? 'Lembramos que o envio é pela modalidade Correios Mini Envios, que possui rastreamento simplificado e pode apresentar atualizações menos frequentes.' : '',
    valor: p.valor != null ? 'R$ ' + Number(p.valor).toFixed(2).replace('.', ',') : '',
    produtos: (p.itens || []).map(i => `${i.q || 1}x ${i.t || ''}`).join(', '), atendente: '',
  };
}
const out = (o) => [{ json: { conv: b.conv, ultimo_in: b.ultimo_in, fernanda: false, ...o } }];
const PADRAO_RASTREIO = 'Olá, {nome}! Tudo bem? 💙\n\nSeu pedido #{pedido} já está a caminho. Seguem os dados para acompanhar:\n\n📦 Código: {rastreio}\n🔎 Link de rastreamento: {link_rastreio}\n📅 Previsão de entrega: {previsao}\n\n{aviso_envio}\n\nEquipe Face Clean 🌿';
const PADRAO_PREP = 'Olá, {nome}! Tudo bem? 💙\n\nSeu pedido #{pedido} já foi faturado e está sendo preparado pra envio 📦\nAssim que for postado, o código de rastreio chega aqui no WhatsApp.\n\nEquipe Face Clean 🌿';
const rastreio = () => {
  const p = b.transito;
  if (!p || !p.rastreio) return null;
  if (refs.has('rastreio:' + p.rastreio)) return out({ acao: 'humano', motivo: 'pediu rastreio de novo (já foi mandado 1x): ' + motivo });
  const hoje = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Fortaleza' })); hoje.setHours(0, 0, 0, 0);
  const prev = p.previsao ? new Date(String(p.previsao).slice(0, 10) + 'T00:00:00') : null;
  if (prev && !isNaN(prev) && prev < hoje) return out({ acao: 'humano', motivo: `pedido atrasado (previsão ${data(p.previsao)} já passou): ` + motivo });
  const ev = p.rastreio_cache && p.rastreio_cache.dados && Array.isArray(p.rastreio_cache.dados.eventos) && p.rastreio_cache.dados.eventos[0];
  if (ev && ev.quando && (Date.now() - Date.parse(ev.quando)) > 6 * 86400000) return out({ acao: 'humano', motivo: 'rastreio parado há mais de 6 dias: ' + motivo });
  if (p.enviado && (Date.now() - Date.parse(p.enviado)) > 15 * 86400000) return out({ acao: 'humano', motivo: 'enviado há mais de 15 dias e não entregue: ' + motivo });
  return out({ acao: 'rastreio', ref: p.rastreio, texto: render(b.ctx.modelos.rastreio || PADRAO_RASTREIO, vars(p)), motivo });
};
const preparando = () => {
  const p = b.preparando;
  if (!p) return null;
  const ref = String(p.numero || '');
  if (!ref || refs.has('preparando:' + ref)) return out({ acao: 'humano', motivo: 'perguntou do pedido de novo (status já foi mandado 1x): ' + motivo });
  return out({ acao: 'preparando', ref, texto: render(b.ctx.modelos['auto-preparando'] || PADRAO_PREP, vars(p)), motivo });
};
if (acao === 'humano') return out({ acao: 'humano', motivo });
if (acao === 'nada') return out({ acao: 'nada', motivo });
if (b.pagos > 0) {
  if (acao === 'rastreio') return rastreio() || preparando() || out({ acao: 'humano', motivo: 'pediu rastreio sem pedido em trânsito: ' + motivo });
  if (acao === 'status') return preparando() || rastreio() || out({ acao: 'humano', motivo: 'perguntou do pedido sem pedido em preparação: ' + motivo });
  return out({ acao: 'humano', motivo: 'cliente que já comprou (IA não vende pra cliente): ' + motivo });
}
if (acao === 'venda' && cfg.ia_venda === 'sim') return out({ acao: 'venda', fernanda: true, motivo });
if (acao === 'venda') return [];
return out({ acao: 'humano', motivo: 'sem compra nesse número falando de pedido: ' + motivo });

const d = $('Fernanda: monta').first().json;
const j = $input.first().json || {};
const c = j.choices && j.choices[0] && j.choices[0].message && j.choices[0].message.content;
if (!c) return [];
let o; try { o = JSON.parse(c); } catch (e) { return []; }
const acao = String(o.acao || '').toLowerCase();
if (acao === 'humano') return [{ json: { conv: d.conv, ultimo_in: d.ultimo_in, acao: 'humano', motivo: 'Fernanda: ' + String(o.motivo || '').slice(0, 120) } }];
let t = String(o.resposta || '').trim();
t = t.replace(/\[([^\]]+)\]\((https?:[^)]+)\)/g, '$2').replace(/\*\*([^*]+)\*\*/g, '*$1*');
const PROIBIDO = /(\bcura\b|\bcurar\b|garant(o|ido|imos) (que|o resultado|100)|100\s?%|milagr|definitiv|elimina de vez|chave pix|n[uú]mero do cart[aã]o|sou (uma )?(ia|rob[oô]|assistente virtual))/i;
if (!t || t.length > 900 || PROIBIDO.test(t)) return [];
return [{ json: { conv: d.conv, ultimo_in: d.ultimo_in, acao: 'venda', texto: t, motivo: 'Fernanda: ' + String(o.motivo || '').slice(0, 120) } }];

const d = $input.first().json || {};
if (!d.conv || !d.acao) return [];
const body = { conv: d.conv, ultimo_in: d.ultimo_in, acao: d.acao, texto: d.texto || '', ref: d.ref || '', motivo: d.motivo || '' };
const b64 = Buffer.from(JSON.stringify({ rota: 'ia_decisao', token: '', body }), 'utf8').toString('base64');
return [{ json: { sql: `select suporte.api(convert_from(decode('${b64}', 'base64'), 'UTF8')::jsonb) as r` } }];
